#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
bool isV(char c){char l=tolower((unsigned char)c);
return l=='a'||l=='e'||l=='i'||l=='o'||l=='u';}
int main(){string s;getline(cin,s);
int i=0,j=(int)s.size()-1;
while(i<j){
while(i<j&&!isV(s[i]))++i;
while(i<j&&!isV(s[j]))--j;
swap(s[i],s[j]);++i;--j;}
printf("%s\n",s.c_str());return 0;}

